-- GeoStats v16.2.6: reason-aware legacy rejection registry and fail-closed activation guard.
-- Generated from the takeover re-audit artifacts; rerunnable and intentionally conservative.
begin;
select pg_advisory_xact_lock(hashtext('geostats-v16.2.6-legacy-rejection-guard'));

create table if not exists public.legacy_category_rejections_v16_2_6 (
  legacy_key text primary key,
  category_title text not null,
  normalized_title text not null,
  legacy_source text not null,
  legacy_domain_series text,
  legacy_source_line integer,
  rejection_basis text not null check(rejection_basis in ('legacy_unexplained','generic_batch_reason','explicit_product_decision','explicit_duplicate')),
  default_decision text not null check(default_decision in ('requires_reaudit','confirmed_exclusion')),
  required_action text not null,
  seeded_at timestamptz not null default now()
);
alter table public.legacy_category_rejections_v16_2_6 enable row level security;
revoke all on public.legacy_category_rejections_v16_2_6 from public,anon,authenticated;
grant select,insert,update,delete on public.legacy_category_rejections_v16_2_6 to service_role;
create index if not exists legacy_category_rejections_v16_2_6_title_idx on public.legacy_category_rejections_v16_2_6(normalized_title);

create table if not exists public.legacy_rejection_semantic_aliases_v16_2_6 (
  alias_normalized_title text not null,
  legacy_key text not null references public.legacy_category_rejections_v16_2_6(legacy_key) on delete cascade,
  tracker_id text,
  current_title text not null,
  collision_basis text not null,
  review_status text not null default 'requires_reaudit' check(review_status in ('requires_reaudit','cleared','confirmed_exclusion')),
  rationale text not null,
  seeded_at timestamptz not null default now(),
  primary key(alias_normalized_title,legacy_key)
);
alter table public.legacy_rejection_semantic_aliases_v16_2_6 enable row level security;
revoke all on public.legacy_rejection_semantic_aliases_v16_2_6 from public,anon,authenticated;
grant select,insert,update,delete on public.legacy_rejection_semantic_aliases_v16_2_6 to service_role;

create table if not exists public.category_legacy_rejection_resolutions_v16_2_6 (
  category_id text not null references public.stat_categories(id) on delete cascade,
  legacy_key text not null references public.legacy_category_rejections_v16_2_6(legacy_key) on delete cascade,
  match_type text not null check(match_type in ('exact_title','source_indicator','semantic')),
  decision text not null check(decision in ('requires_reaudit','cleared_for_reconsideration','confirmed_exclusion')),
  rationale text not null,
  reviewed_at timestamptz not null default now(),
  primary key(category_id,legacy_key)
);
alter table public.category_legacy_rejection_resolutions_v16_2_6 enable row level security;
revoke all on public.category_legacy_rejection_resolutions_v16_2_6 from public,anon,authenticated;
grant select,insert,update,delete on public.category_legacy_rejection_resolutions_v16_2_6 to service_role;

create table if not exists public.tracker_legacy_rejection_collisions_v16_2_6 (
  tracker_id text primary key,
  tracker_title text not null,
  tracker_scope_type text not null,
  tracker_source_candidate text,
  tracker_source_indicator text,
  legacy_source text not null,
  legacy_domain_series text,
  legacy_source_line integer,
  rejection_basis text not null,
  rejection_strength text not null check(rejection_strength in ('requires_first_principles_reaudit','strong_exclusion')),
  tracker_final_disposition text,
  tracker_implementation_status text,
  classified_at timestamptz not null default now()
);
alter table public.tracker_legacy_rejection_collisions_v16_2_6 enable row level security;
revoke all on public.tracker_legacy_rejection_collisions_v16_2_6 from public,anon,authenticated;
grant select,insert,update,delete on public.tracker_legacy_rejection_collisions_v16_2_6 to service_role;

on conflict(legacy_key) do update set category_title=excluded.category_title,normalized_title=excluded.normalized_title,legacy_source=excluded.legacy_source,legacy_domain_series=excluded.legacy_domain_series,legacy_source_line=excluded.legacy_source_line,rejection_basis=excluded.rejection_basis,default_decision=excluded.default_decision,required_action=excluded.required_action;

on conflict(alias_normalized_title,legacy_key) do update set tracker_id=excluded.tracker_id,current_title=excluded.current_title,collision_basis=excluded.collision_basis,review_status=excluded.review_status,rationale=excluded.rationale;

on conflict(tracker_id) do update set tracker_title=excluded.tracker_title,tracker_scope_type=excluded.tracker_scope_type,tracker_source_candidate=excluded.tracker_source_candidate,tracker_source_indicator=excluded.tracker_source_indicator,legacy_source=excluded.legacy_source,legacy_domain_series=excluded.legacy_domain_series,legacy_source_line=excluded.legacy_source_line,rejection_basis=excluded.rejection_basis,rejection_strength=excluded.rejection_strength,tracker_final_disposition=excluded.tracker_final_disposition,tracker_implementation_status=excluded.tracker_implementation_status;

create or replace function public.category_legacy_rejection_blockers_v16_2_6(p_category_id text,p_title text)
returns text[]
language sql
stable
security definer
set search_path=public
as $$
  with exact_matches as (
    select r.legacy_key,r.default_decision
    from public.legacy_category_rejections_v16_2_6 r
    where r.normalized_title=regexp_replace(lower(coalesce(p_title,'')),'[^a-z0-9]+','','g')
  ), semantic_alias_matches as (
    select r.legacy_key,
      case when a.review_status='confirmed_exclusion' then 'confirmed_exclusion' else 'requires_reaudit' end as default_decision
    from public.legacy_rejection_semantic_aliases_v16_2_6 a
    join public.legacy_category_rejections_v16_2_6 r on r.legacy_key=a.legacy_key
    where a.alias_normalized_title=regexp_replace(lower(coalesce(p_title,'')),'[^a-z0-9]+','','g')
      and a.review_status<>'cleared'
  ), linked_matches as (
    select r.legacy_key,r.default_decision
    from public.category_legacy_rejection_resolutions_v16_2_6 x
    join public.legacy_category_rejections_v16_2_6 r on r.legacy_key=x.legacy_key
    where x.category_id=p_category_id
  ), matches as (
    select * from exact_matches
    union select * from semantic_alias_matches
    union select * from linked_matches
  )
  select coalesce(array_agg(m.legacy_key order by m.legacy_key) filter(
    where coalesce(x.decision,m.default_decision)<>'cleared_for_reconsideration'
  ),'{}'::text[])
  from matches m
  left join public.category_legacy_rejection_resolutions_v16_2_6 x
    on x.category_id=p_category_id and x.legacy_key=m.legacy_key;
$$;
revoke all on function public.category_legacy_rejection_blockers_v16_2_6(text,text) from public,anon,authenticated;
grant execute on function public.category_legacy_rejection_blockers_v16_2_6(text,text) to service_role;

-- Append the guard to the existing runtime view without changing existing column order.
create or replace view public.category_runtime_review_v16_2
with(security_invoker=true) as
select
  v.*,
  a.proposed_status as promotion_decision_v16_2,
  a.reason as promotion_reason_v16_2,
  a.primary_blocker as primary_blocker_v16_2,
  a.blocker_class as blocker_class_v16_2,
  a.strict_pass as strict_pass_v16_2,
  a.source_quality_floor as source_quality_floor_v16_2,
  a.suggested_duplicate_of as suggested_duplicate_of_v16_2,
  (
    a.proposed_status='playable'
    and v.editorial_status='approved'
    and a.strict_pass
    and public.category_v16_2_6_hard_block_reason(c.id,c.source_organization,c.source_indicator_code,v.effective_title,c.metadata) is null
    and cardinality(legacy.blockers)=0
  ) as computed_playable_v16_2,
  array_remove(array[
    case when a.proposed_status<>'playable' then a.primary_blocker end,
    public.category_v16_2_6_hard_block_reason(c.id,c.source_organization,c.source_indicator_code,v.effective_title,c.metadata),
    case when cardinality(legacy.blockers)>0 then 'legacy_rejection_reaudit' end
  ],null) as v16_2_blockers,
  array_remove(array[
    case when v.validation_status<>'verified'
      and not public.category_v15_true_integrity_failure(
        v.validation_status,v.validation_reason,
        v.validation_mismatch_count,v.validation_ranking_mismatch_count
      ) then 'Official values are usable; non-data source metadata remain incomplete.' end,
    case when v.ranking_completeness_status='top_end_complete' then 'Ranking is top-end complete rather than fully comprehensive.' end,
    case when v.player_source_status='general' then 'Uses a general official source page rather than an exact shareable view.' end
  ],null) as v16_2_warnings,
  c.measurement_type,
  legacy.blockers as legacy_rejection_blockers_v16_2_6
from public.category_runtime_review_v16 v
join public.category_promotion_assessment_v16_2 a on a.category_id=v.id
join public.stat_categories c on c.id=v.id
cross join lateral (
  select public.category_legacy_rejection_blockers_v16_2_6(c.id,v.effective_title) as blockers
) legacy;
revoke all on public.category_runtime_review_v16_2 from public,anon,authenticated;
grant select on public.category_runtime_review_v16_2 to service_role;

drop view if exists public.category_review_workbench_v16_2;
create view public.category_review_workbench_v16_2
with(security_invoker=true) as
select runtime.*,
 vetting.recommendation as auto_vetting_recommendation,
 vetting.vetting_score as auto_vetting_score,
 vetting.reason as auto_vetting_reason,
 vetting.possible_duplicate_of as auto_possible_duplicate_of,
 vetting.title_similarity as auto_title_similarity,
 vetting.rank_correlation as auto_rank_correlation,
 vetting.tie_share as auto_tie_share,
 vetting.vetting_version as auto_vetting_version,
 vetting.vetted_at as auto_vetted_at
from public.category_runtime_review_v16_2 runtime
left join public.category_auto_vetting_v15_9 vetting on vetting.category_id=runtime.id;
revoke all on public.category_review_workbench_v16_2 from public,anon,authenticated;
grant select on public.category_review_workbench_v16_2 to service_role;

-- Any exact-title collision or explicitly linked semantic/source collision now
-- fails closed unless a reviewed resolution explicitly clears reconsideration.
update public.stat_categories c
set enabled=false,eligible_daily=false,updated_at=now()
from public.category_runtime_review_v16_2 v
where v.id=c.id and cardinality(v.legacy_rejection_blockers_v16_2_6)>0;

commit;
